package dev.industrialtechnology.client.space;
import cpw.mods.fml.common.FMLCommonHandler;import cpw.mods.fml.common.eventhandler.SubscribeEvent;import cpw.mods.fml.common.gameevent.TickEvent;import cpw.mods.fml.client.registry.*;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.*;import net.minecraft.nbt.NBTTagCompound;import net.minecraftforge.common.MinecraftForge;import net.minecraftforge.event.world.WorldEvent;import net.minecraftforge.client.event.*;import org.lwjgl.opengl.GL11;import dev.industrialtechnology.space.*;
public final class SpaceClient {
    private static int particlesLeft;private static NBTTagCompound hud=new NBTTagCompound();
    public static void init(){RenderingRegistry.registerBlockHandler(new FacilityPartRenderer());SpaceClient e=new SpaceClient();MinecraftForge.EVENT_BUS.register(e);FMLCommonHandler.instance().bus().register(e);ClientRegistry.bindTileEntitySpecialRenderer(TileSpaceMachine.class,new SpaceMachineRenderer());ClientRegistry.bindTileEntitySpecialRenderer(TileLaunchFacility.class,new LaunchFacilityRenderer());RenderingRegistry.registerEntityRenderingHandler(EntitySpaceRocket.class,new RocketRenderer());}
    public static void receive(int window,NBTTagCompound state){Minecraft mc=Minecraft.getMinecraft();if(state==null||mc.thePlayer==null)return;if(window==-1){hud=state;return;}if(mc.currentScreen instanceof GuiSpace){GuiSpace g=(GuiSpace)mc.currentScreen;if(g.container.windowId==window)g.state=state;}}
    @SubscribeEvent public void tick(TickEvent.ClientTickEvent e){if(e.phase==TickEvent.Phase.START){particlesLeft=SpaceConfig.particleBudget;return;}Minecraft mc=Minecraft.getMinecraft();if(mc.theWorld!=null&&mc.theWorld.provider instanceof WorldProviderPlanet&&!(mc.theWorld.provider.getSkyRenderer() instanceof PlanetSky))mc.theWorld.provider.setSkyRenderer(new PlanetSky());
        if(storm()&&particlesLeft>0&&mc.thePlayer!=null&&mc.theWorld.canBlockSeeTheSky((int)mc.thePlayer.posX,(int)mc.thePlayer.posY+2,(int)mc.thePlayer.posZ)){int count=Math.min(3,particlesLeft);particlesLeft-=count;for(int i=0;i<count;i++)mc.theWorld.spawnParticle("reddust",mc.thePlayer.posX+(mc.theWorld.rand.nextDouble()-.5)*16,mc.thePlayer.posY+mc.theWorld.rand.nextDouble()*5,mc.thePlayer.posZ+(mc.theWorld.rand.nextDouble()-.5)*16,.8,.35,.2);}}
    @SubscribeEvent public void lowDistanceSky(net.minecraftforge.client.event.RenderWorldLastEvent e){Minecraft mc=Minecraft.getMinecraft();if(mc.theWorld!=null&&mc.gameSettings.renderDistanceChunks<4&&mc.theWorld.provider instanceof WorldProviderPlanet&&mc.theWorld.provider.getSkyRenderer() instanceof PlanetSky)((PlanetSky)mc.theWorld.provider.getSkyRenderer()).renderBehindTerrain(e.partialTicks,mc.theWorld,mc);}
    @SubscribeEvent public void textures(net.minecraftforge.client.event.TextureStitchEvent.Pre e){if(e.map.getTextureType()!=0)return;String[] names={"crude_oil","kerosene","oxygen","liquid_oxygen","breathable_air"};for(int i=1;i<=5;i++)SpaceRegistry.fluidFor(i).setIcons(e.map.registerIcon("industrialtech:fluids/"+names[i-1]));}
    @SubscribeEvent public void density(EntityViewRenderEvent.FogDensity e){if(storm()){GL11.glFogi(GL11.GL_FOG_MODE,GL11.GL_EXP);e.density=.022f;e.setCanceled(true);}}

    public static void particles(EntitySpaceRocket r){Minecraft mc=Minecraft.getMinecraft();if(mc.isGamePaused()||SpaceConfig.particleBudget<=0||mc.theWorld!=r.worldObj)return;int budget=Math.min(particlesLeft,r.visualPhase()==EntitySpaceRocket.ASCENT?8:3);particlesLeft-=budget;for(int i=0;i<budget;i++){double x=r.posX+(r.worldObj.rand.nextDouble()-.5)*.6,z=r.posZ+(r.worldObj.rand.nextDouble()-.5)*.6;double y=r.posY+.3;if(r.shuttle()){int nozzle=i%5;double xx=nozzle==0?-6.4:nozzle==1?6.4:nozzle==2?-1.25:nozzle==3?1.25:0,zz=nozzle<2?0:nozzle==4?9.1:7;double angle=Math.toRadians(r.rotationYaw);x=r.posX+Math.cos(angle)*xx+Math.sin(angle)*zz+(r.worldObj.rand.nextDouble()-.5)*.8;z=r.posZ-Math.sin(angle)*xx+Math.cos(angle)*zz+(r.worldObj.rand.nextDouble()-.5)*.8;y=r.posY+(nozzle<2?0:10);}r.worldObj.spawnParticle(i%3==0?"flame":"largesmoke",x,y,z,0,-.2-r.worldObj.rand.nextDouble()*.1,0);}}
    private boolean storm(){Minecraft mc=Minecraft.getMinecraft();return mc.theWorld!=null&&mc.thePlayer!=null&&mc.theWorld.provider.dimensionId==SpaceConfig.mars&&SpaceConfig.dustStorms&&Math.floorMod(mc.theWorld.getTotalWorldTime()/12000+((long)mc.thePlayer.posX>>10)*31+((long)mc.thePlayer.posZ>>10)*17+mc.theWorld.getSeed(),5)==0;}
    @SubscribeEvent public void fog(EntityViewRenderEvent.FogColors e){if(storm()){e.red=.45f;e.green=.25f;e.blue=.15f;}}
    @SubscribeEvent public void render(RenderGameOverlayEvent.Post e){if(e.type!=RenderGameOverlayEvent.ElementType.ALL)return;Minecraft mc=Minecraft.getMinecraft();if(mc.thePlayer==null||SpaceDimensions.planet(mc.thePlayer.dimension)<0)return;GL11.glPushAttrib(GL11.GL_ALL_ATTRIB_BITS);try{GL11.glDisable(GL11.GL_LIGHTING);GL11.glDisable(GL11.GL_DEPTH_TEST);Gui.drawRect(4,4,230,39,0x990b1013);int secs=hud.getInteger("Air");String air=hud.getBoolean("Breathable")?"PRESSURIZED / CABIN":"AIR "+secs/60+":"+String.format(java.util.Locale.ROOT,"%02d",secs%60);mc.fontRenderer.drawStringWithShadow(air+"   "+hud.getInteger("Pressure")+"%",8,8,0xa9dfc3);double day=mc.theWorld.getCelestialAngle(0);int temp=mc.thePlayer.dimension==SpaceConfig.moon?(int)(-173+300*Math.max(0,Math.cos(day*Math.PI*2))):(int)(-90+110*Math.max(0,Math.cos(day*Math.PI*2)));mc.fontRenderer.drawStringWithShadow((mc.thePlayer.dimension==SpaceConfig.moon?"Moon  0.165 g":"Mars  0.38 g")+"  "+temp+"\u00b0C"+(storm()?" DUST":""),8,18,0xd8c19a);String warning=hud.getString("Warning");if(!warning.isEmpty())mc.fontRenderer.drawStringWithShadow(warning,8,28,0xff775b);}finally{GL11.glPopAttrib();GL11.glColor4f(1,1,1,1);}}
}
